import type { ClientModule } from 'claude-code'

import { landingFrameOf, segmentsOf } from '../stamp'
import type { StampColors } from '../stamp'

type Props = { rows: string[]; starts: number[]; width: number } & StampColors
type State = { step: number }

const FRAME_MS = 40

/**
 * The verdict landing: it drops in from above, overshoots one row, shakes
 * one column as it lands wet with ink, and dries. One colour throughout: it
 * never flashes.
 */
const Entrance: ClientModule<Props, State> = (props, surface) => {
  const { Box, Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ step: 0 })
    const stop = surface.every(FRAME_MS, () => {
      const step = (surface.state?.step ?? 0) + 1
      surface.setState({ step })
      if (landingFrameOf(props.rows, step).isLast) {
        stop()
      }
    })
  }
  const frame = landingFrameOf(props.rows, surface.state?.step ?? 0)
  return Box({
    flexDirection: 'column',
    children: frame.rows.map(row =>
      Box({ children: segmentsOf(row, Infinity, props).map(run => Text({ color: run.color, children: run.text })) }),
    ),
  })
}

export default Entrance

files.hooks/clients/gavel.ts:
import type { ClientModule } from 'claude-code'

import { GAVEL } from '../stamp'

type Props = { color: string }
type State = { tick: number }

const TICK_MS = 70

/**
 * Ticks the gavel is held up before it falls, then the one between.
 */
const RAISED_TICKS = 7

/**
 * "ALL RISE.": the gavel held up, swung, and struck, once. Then it rests on
 * the strike; it never repeats.
 */
const Gavel: ClientModule<Props, State> = (props, surface) => {
  const { Box, Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ tick: 0 })
    const stop = surface.every(TICK_MS, () => {
      const tick = (surface.state?.tick ?? 0) + 1
      surface.setState({ tick })
      if (tick > RAISED_TICKS) {
        stop()
      }
    })
  }
  const tick = surface.state?.tick ?? 0
  const pose = tick < RAISED_TICKS ? 'raised' : tick === RAISED_TICKS ? 'swing' : 'struck'
  return Box({
    flexDirection: 'column',
    children: GAVEL[pose].map(row => Text({ color: props.color, children: row })),
  })
}

export default Gavel

files.hooks/clients/scales.ts:
import type { ClientModule } from 'claude-code'

import { SCALES } from '../stamp'

type Props = { color: string }
type State = { tick: number }

/**
 * How long the pans hold each position while the jury deliberates: within
 * the shortest deliberation they tip one way, the other, and back.
 */
const BOB_MS = 450

/**
 * The scales of justice: level, then the pans tipping one way and the other
 * while the jury deliberates, on the drawing's own frame clock.
 */
const Scales: ClientModule<Props, State> = (props, surface) => {
  const { Box, Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ tick: 0 })
    surface.every(BOB_MS, () => surface.setState({ tick: (surface.state?.tick ?? 0) + 1 }))
  }
  const tick = surface.state?.tick ?? 0
  const position = tick === 0 ? 'level' : tick % 2 === 1 ? 'left' : 'right'
  return Box({
    flexDirection: 'column',
    children: SCALES[position].map(row => Text({ color: props.color, children: row })),
  })
}

export default Scales

files.hooks/clients/typed.ts:
import type { ClientModule } from 'claude-code'

import { MS_PER_CHAR } from '../pace'

type Props = { text: string }
type State = { chars: number }

const TICK_MS = 20
const CHARS_PER_TICK = TICK_MS / MS_PER_CHAR

/**
 * A speech typed out as it is delivered, at the pace the hooks module plans
 * the trial by, on the drawing's own frame clock. Stops its timer once the
 * speech is whole.
 */
const Typed: ClientModule<Props, State> = (props, surface) => {
  const { Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ chars: 0 })
    const stop = surface.every(TICK_MS, () => {
      const chars = (surface.state?.chars ?? 0) + CHARS_PER_TICK
      surface.setState({ chars })
      if (chars >= props.text.length) {
        stop()
      }
    })
  }
  return Text({ children: props.text.slice(0, surface.state?.chars ?? 0) })
}

export default Typed

files.hooks/clients/deliberation.ts:
import type { ClientModule } from 'claude-code'

import { gaugeOf } from '../gauge'

type Props = { deadlineMs: number; cells: number; color: string }
type State = { ticks: number }

/**
 * One frame of the countdown, in milliseconds.
 */
const TICK_MS = 150

/**
 * The court's deadline as a bar that fills and the seconds left beside it,
 * on the drawing's own frame clock, so the hooks module redraws nothing
 * while it moves.
 */
const Deliberation: ClientModule<Props, State> = (props, surface) => {
  const { Box, Text } = surface.elements
  if (surface.state === undefined) {
    surface.setState({ ticks: 0 })
    surface.every(TICK_MS, () => surface.setState({ ticks: (surface.state?.ticks ?? 0) + 1 }))
  }
  const elapsed = (surface.state?.ticks ?? 0) * TICK_MS
  const { filled, track } = gaugeOf(elapsed / props.deadlineMs, props.cells)
  const left = Math.max(0, Math.ceil((props.deadlineMs - elapsed) / 1000))
  return Box({
    children: [
      Box({ key: 'filled', children: [Text({ color: props.color, children: filled })] }),
      Text({ dimColor: true, children: track }),
      Text({ children: '  ' }),
      Box({ key: 'left', children: [Text({ dimColor: true, children: `${left}s left` })] }),
    ],
  })
}

export default Deliberation

